def release_prepare_cmd():
    """R6-01A: run release-time shared-state mutation ONCE, then prove head.

    The single migration authority for a dual-revision release: Alembic upgrade
    (bounded lock wait), fresh-schema bootstrap, seeds and the referral
    backfill — then the same read-only readiness proof a read-only web
    candidate runs. It never rebuilds the canonical leaderboard sets: another
    revision may be serving from them while this runs.

    Must be run from a process that did no startup DB work itself:
        FITX_SKIP_DB_INIT=1 flask --app starter release-prepare
    """
    from flask import current_app

    from app.db_init import prepare_release
    from app.schema_safety import (StartupMode, resolve_startup_mode,
                                   verify_schema_ready)

    mode = resolve_startup_mode()
    if mode is not StartupMode.SKIP_DB_INIT:
        raise click.ClickException(
            f"release-prepare requires FITX_SKIP_DB_INIT=1 (startup mode is "
            f"{mode.value}); the app factory must not have prepared already.")
    app = current_app._get_current_object()
    prepare_release(app)
    heads = verify_schema_ready(app)
    click.echo(f"release-prepare: schema at head {','.join(sorted(heads))}")


def ai_allowance_sweep_cmd():
    """MON-02-BE-03A: settle abandoned AI allowance holds and purge old records.

    Refuses while AI_ALLOWANCE_LEDGER_ENABLED is OFF. Safe to repeat.

        flask --app starter ai-allowance-sweep
    """
    from app.services import ai_allowances
    try:
        expired = ai_allowances.expire_abandoned()
        settled, periods = ai_allowances.purge_retained()
    except ai_allowances.AllowanceError as error:
        raise click.ClickException(error.code) from None
    click.echo(f"expired={expired} purged_settled={settled} purged_periods={periods}")


@click.option("--limit", default=25, show_default=True, type=click.IntRange(1, 200))
@click.option("--sweep-limit", default=50, show_default=True, type=click.IntRange(0, 500))
def apple_subscription_reconcile_cmd(limit, sweep_limit):
    """MON-02-BE-02: one bounded pass of authoritative Apple reconciliation.

    One pass per verified environment: with APPLE_SANDBOX_FALLBACK_ENABLED a
    Production deployment also passes over Sandbox, so up to 2 x --limit lookups.

    Refuses while both APPLE_SUBSCRIPTIONS_ENABLED and APPLE_NOTIFICATIONS_ENABLED
    are OFF or Apple configuration is incomplete. Financial evidence can refresh
    under intake-only authorization; paid access stays gated independently.
    Production cadence belongs to the separately installed R6 active-release timer.

        flask --app starter apple-subscription-reconcile
    """
    from app.services import apple_reconciliation
    try:
        counts = apple_reconciliation.run(limit=limit, sweep_limit=sweep_limit)
    except (apple_reconciliation.ReconciliationDisabled,
            apple_reconciliation.ReconciliationUnavailable) as error:
        raise click.ClickException(str(error)) from None
    click.echo(" ".join(f"{key}={counts[key]}" for key in sorted(counts)))


COMPLETION_FLOOR_PREFIX = "completion-floor: "


def _emit_machine_line(prefix, payload, failed=False):
    """ONE machine-readable line (release tooling parses exactly this prefix)."""
    import json
    click.echo(prefix + json.dumps(payload, sort_keys=True))
    if failed:
        raise SystemExit(1)


def _completion_floor_emit(payload, failed=False):
    _emit_machine_line(COMPLETION_FLOOR_PREFIX, payload, failed)


# AppGroup like every other command here: the subcommands get the application
# context on every invocation path (the `flask` executable and `app.cli` alike),
# so the release-tooling contract can be exercised in-process.
@click.group("completion-floor", cls=AppGroup)
def completion_floor_cmd():
    """PRIV-K6 completion capability floor (read or raise; never lower).

        FITX_SKIP_DB_INIT=1 flask --app starter completion-floor status
        FITX_SKIP_DB_INIT=1 flask --app starter completion-floor raise --revision <sha>
    """


@completion_floor_cmd.command("status")
def completion_floor_status_cmd():
    """Read-only: floor, fence verification, whether any claim exists."""
    from app.services import completion_fence
    try:
        with db.engine.connect() as connection:
            status = completion_fence.floor_status(connection)
    except completion_fence.FloorError as exc:
        _completion_floor_emit({"result": "error", "reason": exc.reason}, failed=True)
    except Exception as exc:  # noqa: BLE001 - unknown is reported, never "absent"
        _completion_floor_emit({"result": "error", "reason": type(exc).__name__},
                               failed=True)
    _completion_floor_emit({"result": "ok", **status})


@completion_floor_cmd.command("raise")
@click.option("--revision", required=True, help="40-hex release revision raising it.")
def completion_floor_raise_cmd(revision):
    """Raise the floor under the exclusive floor lock (idempotent)."""
    from app.services import completion_fence
    try:
        with db.engine.connect() as connection:
            outcome = completion_fence.raise_floor(connection, revision)
    except completion_fence.FloorError as exc:
        _completion_floor_emit({"result": "refused", "reason": exc.reason}, failed=True)
    except Exception as exc:  # noqa: BLE001 - lock timeout, refusal, outage
        refusal = completion_fence.refusal_of(exc)
        _completion_floor_emit({"result": "error", "reason": (
            refusal.reason if refusal else type(exc).__name__)}, failed=True)
    _completion_floor_emit(outcome)


SCHEMA_HEADS_PREFIX = "schema-heads: "


def schema_heads_cmd():
    """R6-R1-28 forward recovery: the database's current Alembic heads, read-only.

    One machine line; the deploy transaction parses exactly this prefix and
    treats anything else as unknown (never as "not migrated").

        FITX_SKIP_DB_INIT=1 flask --app starter schema-heads
    """
    from app.schema_safety import _read_current_heads
    try:
        has_table, current = _read_current_heads(db.engine)
    except Exception as exc:  # noqa: BLE001 - unknown is reported, never guessed
        _emit_machine_line(SCHEMA_HEADS_PREFIX,
                           {"result": "error", "reason": type(exc).__name__},
                           failed=True)
    _emit_machine_line(SCHEMA_HEADS_PREFIX, {"result": "ok", "has_table": has_table,
                                             "current": sorted(current or ())})


@click.option("--expect-meal-log", type=int, required=True,
              help="Expected legacy provider meal_log rows (DB4: 3).")
@click.option("--expect-items", type=int, required=True,
              help="Expected legacy provider saved-meal items (DB4: 26).")
def fatsecret_retention_legacy_dry_run_cmd(expect_meal_log, expect_items):
    """Read-only dry run of the founder-gated FatSecret legacy disposition.

    Prints aggregates only and mutates nothing; no apply mode exists. Exits 0
    with RESULT=MATCH only when the counts equal the expected DB4 counts and
    every affected day total is conserved; otherwise RESULT=HOLD, exit 2.

        flask --app starter fatsecret-retention-legacy-dry-run \\
            --expect-meal-log 3 --expect-items 26
    """
    import json as _json
    from app.services import provider_retention
    report = provider_retention.legacy_dry_run()
    match = (report["meal_log_provider_rows"] == expect_meal_log
             and report["custom_meal_item_provider_items"] == expect_items
             and report["day_totals_conserved"])
    report.update({"mode": "dry_run", "mutation": "none",
                   "expected": {"meal_log": expect_meal_log, "items": expect_items},
                   "RESULT": "MATCH" if match else "HOLD"})
    click.echo(_json.dumps(report, sort_keys=True))
    if not match:
        raise SystemExit(2)


@click.option("--apply", "apply_", is_flag=True,
              help="Delete the keys (founder-gated). Default: count only.")
@click.option("--expect", type=int, default=None,
              help="Required with --apply: the count a prior dry run printed.")
def fatsecret_retention_redis_v1_cmd(apply_, expect):
    """Old FatSecret-era macro cache keys ``food:macros:v1:*`` (post-deploy).

    Default prints the count only. ``--apply --expect N`` UNLINKs exactly that
    pattern and only when a fresh scan still finds N keys (else HOLD, exit 2).
    Production use is separately founder-gated.
    """
    import json as _json
    from app.services import provider_retention
    if not apply_:
        click.echo(_json.dumps({"mode": "dry_run", "pattern": provider_retention.LEGACY_V1_CACHE_PATTERN,
                                "keys": provider_retention.legacy_v1_cache_keys()}))
        return
    if expect is None:
        raise click.UsageError("--apply requires --expect N from a dry run")
    result = provider_retention.unlink_legacy_v1_cache(expect)
    click.echo(_json.dumps(result, sort_keys=True))
    if result["result"] != "DELETED":
        raise SystemExit(2)

@click.option("--limit", default=200, show_default=True, type=int)
def health_erasure_run_cmd(limit):
    """Retry all unfinished erasures; limit sets the batch size, not a total cap."""
    from app.services import health_erasure
    click.echo(json.dumps(health_erasure.run_pending(limit), sort_keys=True))


@click.option("--user-id", required=True, type=int)
@click.option("--matter", required=True, help="Documented claim/request reference (no health content).")
@click.option("--review-date", required=True, help="YYYY-MM-DD: when the hold must be reviewed.")
@click.option("--category", "categories", multiple=True, required=True,
              help="Health category to keep; repeat for each one needed for the matter.")
def health_legal_hold_add_cmd(user_id, matter, review_date, categories):
    """Controller only: exempt named health categories of one owner for one matter."""
    from app.health_consent_models import HealthLegalHold
    from app.models import User
    from app.services import health_erasure
    unknown = sorted(set(categories) - set(health_erasure.CATEGORIES))
    if unknown:
        raise click.UsageError(f"unknown categories: {', '.join(unknown)}")
    matter = matter.strip()
    if not matter or len(matter) > 120:
        raise click.UsageError("matter must be 1-120 characters")
    review = datetime.strptime(review_date, "%Y-%m-%d")
    now = datetime.utcnow()
    if review <= now:
        raise click.UsageError("review date must be in the future")
    from app.services import health_consent
    # Same authority as erasure: a committed hold precedes any storage deletion.
    with health_consent._authority(user_id, exclusive=True):
        if db.session.get(User, user_id) is None:
            raise click.UsageError("no such user")
        hold = HealthLegalHold(owner_id=user_id, categories=sorted(set(categories)),
                               matter_ref=matter, created_at=now, review_at=review)
        db.session.add(hold)
        db.session.commit()
        result = {"hold_id": hold.id, "categories": hold.categories}
    click.echo(json.dumps(result))


@click.option("--hold-id", required=True, type=int)
def health_legal_hold_release_cmd(hold_id):
    """Release a hold; the owner's pending erasure then completes on its next run."""
    from app.health_consent_models import HealthLegalHold
    from app.services import health_erasure
    from app.services import health_consent
    owner = db.session.query(HealthLegalHold.owner_id).filter_by(id=hold_id).scalar()
    db.session.rollback()
    if owner is None:
        raise click.UsageError("no active hold with that id")
    with health_consent._authority(owner, exclusive=True):
        hold = db.session.get(HealthLegalHold, hold_id)
        if hold is None or hold.released_at is not None:
            raise click.UsageError("no active hold with that id")
        hold.released_at = datetime.utcnow()
        db.session.commit()
    try:
        outcome = health_erasure.run(owner)
    except health_erasure.ErasureUnavailable:
        outcome = "pending"
    click.echo(json.dumps({"hold_id": hold_id, "erasure": outcome}))


def health_legal_hold_list_cmd():
    """Active holds: ids, owner, categories, review date. Matter text is not printed."""
    from app.health_consent_models import HealthLegalHold
    rows = HealthLegalHold.query.filter(HealthLegalHold.released_at.is_(None)).order_by(
        HealthLegalHold.review_at).all()
    for hold in rows:
        click.echo(json.dumps({"hold_id": hold.id, "owner_id": hold.owner_id,
                               "categories": hold.categories,
                               "review_at": hold.review_at.date().isoformat(),
                               "review_due": hold.review_at <= datetime.utcnow()}))


